local bin = table.concat(partes)
local chave = 167
local saida = {}

for i = 1, #bin, 8 do
    local byte = tonumber(bin:sub(i, i + 7), 2)
    if not byte then
        error("LK: dados binarios invalidos")
    end
    byte = bit32 and bit32.bxor(byte, chave) or ((byte + 256 - chave) % 256)
    saida[#saida + 1] = string.char(byte)
end

local codigo = table.concat(saida)
local executar = loadstring or load
if not executar then
    error("LK: este executor nao oferece loadstring/load")
end

local fn, erro = executar(codigo)
if not fn then
    error("LK: falha ao carregar script: " .. tostring(erro))
end
return fn()
